using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Threading.Tasks;
class Setup:Form {
 ComboBox language=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=160};Button install=new Button{Width=180,Height=40};Label info=new Label{AutoSize=false,Width=555,Height=130};Label state=new Label{Width=555,Height=60};bool english;string source=AppDomain.CurrentDomain.BaseDirectory;
 Setup(){Text="3DSTL Setup / 安装";ClientSize=new Size(610,350);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",10);var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),FlowDirection=FlowDirection.TopDown};Controls.Add(panel);panel.Controls.Add(new Label{Text="3DSTL",Font=new Font(Font.FontFamily,24,FontStyle.Bold),Height=48,AutoSize=true});language.Items.AddRange(new object[]{"简体中文","English"});language.SelectedIndex=0;language.SelectedIndexChanged+=delegate{english=language.SelectedIndex==1;RefreshText();};panel.Controls.Add(language);panel.Controls.Add(info);panel.Controls.Add(install);panel.Controls.Add(state);install.Click+=async delegate{install.Enabled=false;try{if(!Environment.Is64BitOperatingSystem)throw new IOException(english?"Windows x64 is required.":"需要64位Windows。");string runtime=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet","shared","Microsoft.WindowsDesktop.App");if(!Directory.Exists(runtime)||!Directory.GetDirectories(runtime,"8.*").Any()){state.Text=english?"Installing Microsoft .NET Desktop Runtime…":"正在安装微软 .NET 桌面运行时…";var start=new ProcessStartInfo(Path.Combine(source,"prerequisites","windowsdesktop-runtime-8.0.29-win-x64.exe"),"/install /passive /norestart"){UseShellExecute=true,Verb="runas"};using(var p=Process.Start(start)){await Task.Run(()=>p.WaitForExit());if(p.ExitCode!=0&&p.ExitCode!=3010)throw new IOException(english?"Runtime installation was not completed.":"运行时安装未完成。");}}string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"3DSTL","App");state.Text=english?"Installing files…":"正在安装程序文件…";await Task.Run(()=>{foreach(string file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){string relative=file.Substring(source.Length);if(relative.StartsWith("prerequisites",StringComparison.OrdinalIgnoreCase))continue;string dest=Path.Combine(target,relative);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(file,dest,true);}});string exe=Path.Combine(target,"manager","3DSTL.exe");using(var p=Process.Start(new ProcessStartInfo(exe,"--repair 3mf stl obj ply off amf gcode gco step stp"){UseShellExecute=false,CreateNoWindow=true})){await Task.Run(()=>p.WaitForExit());if(p.ExitCode!=0)throw new IOException(english?"Association setup failed; open the manager and repair.":"缩略图注册未完成，请打开管理器点击修复。");}Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"3DSTL.lnk"));link.TargetPath=exe;link.WorkingDirectory=target;link.Save();state.Text=english?"Installed. Desktop shortcut created.":"安装完成，桌面已建立3DSTL快捷方式。";Process.Start(new ProcessStartInfo(exe){UseShellExecute=true});}catch(Exception e){state.Text=e.Message;}finally{install.Enabled=true;}};RefreshText();}
 void RefreshText(){install.Text=english?"Install / Repair":"安装 / 修复";info.Text=english?"Free model thumbnails for Windows File Explorer.\r\nAuthor: BA2IA · QQ: 21780 · Thanks to Codex\r\nOriginal source: MIT. Dependencies retain their licenses.\r\nInstalls for the current user; model files are not changed.":"免费模型缩略图，支持资源管理器和桌面。\r\n作者：BA2IA · QQ：21780 · 感谢 Codex\r\n原创源码采用 MIT；第三方组件保留各自许可。\r\n安装到当前用户目录，不修改模型文件。";}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.Run(new Setup());}
